function drawText(text, x, y, color = '#ffffff', scale = 1, center = false) {
  text = String(text).toUpperCase();
  const charStep = 4 * scale;
  const totalWidth = Math.max(0, text.length * charStep - scale);
  let startX = center ? Math.round(x - totalWidth / 2) : Math.round(x);
  ctx.fillStyle = color;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const rows = FONT[ch];
    if (!rows) continue;
    const gx = startX + i * charStep;
    for (let r = 0; r < 5; r++) {
      const row = rows[r];
      for (let c = 0; c < 3; c++) {
        if (row[c] === '1') {
          ctx.fillRect(gx + c * scale, y + r * scale, scale, scale);
        }
      }
    }
  }
}

function textWidth(text, scale = 1) {
  return Math.max(0, String(text).length * 4 * scale - scale);
}

// ---------------------------------------------------------------------------
// Sprite factory
// ---------------------------------------------------------------------------
function makeSprite(rows, palette) {
  let w = 0;
  for (const r of rows) w = Math.max(w, r.length);
  const h = rows.length;
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  for (let y = 0; y < h; y++) {
    const row = rows[y];
    for (let x = 0; x < row.length; x++) {
      const ch = row[x];
      if (ch === '.' || ch === ' ') continue;
      const col = palette[ch];
      if (!col) continue;
      g.fillStyle = col;
      g.fillRect(x, y, 1, 1);
    }
  }
  return c;
}

