function drawSprite(spr, x, y, alpha = 1) {
  if (alpha !== 1) ctx.globalAlpha = alpha;
  ctx.drawImage(spr, Math.round(x - spr.width / 2), Math.round(y - spr.height / 2));
  if (alpha !== 1) ctx.globalAlpha = 1;
