// ---------------------------------------------------------------------------
// Audio
// ---------------------------------------------------------------------------
let audioCtx = null;
let muted = false;

function initAudio() {
  if (audioCtx) {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    return;
  }
  try {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  } catch (e) {
    audioCtx = null;
  }
}

function beepAt(freq, start, dur, type = 'square', vol = 0.08, slideTo = null) {
  if (muted || !audioCtx) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(Math.max(1, freq), start);
  if (slideTo) {
    osc.frequency.exponentialRampToValueAtTime(Math.max(1, slideTo), start + dur);
  }
  gain.gain.setValueAtTime(vol, start);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + dur);
  osc.connect(gain);
  gain.connect(audioCtx.destination);
  osc.start(start);
  osc.stop(start + dur + 0.02);
}

function beep(freq, dur, type = 'square', vol = 0.08, slideTo = null) {
  if (!audioCtx) return;
  beepAt(freq, audioCtx.currentTime, dur, type, vol, slideTo);
}

function noiseBurst(dur, vol = 0.12, cutoff = 1200) {
  if (muted || !audioCtx) return;
  const t = audioCtx.currentTime;
  const n = Math.max(1, Math.floor(audioCtx.sampleRate * dur));
  const buf = audioCtx.createBuffer(1, n, audioCtx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < n; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / n);
  const src = audioCtx.createBufferSource();
  src.buffer = buf;
  const filter = audioCtx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = cutoff;
  const gain = audioCtx.createGain();
  gain.gain.setValueAtTime(vol, t);
  gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(filter);
  filter.connect(gain);
  gain.connect(audioCtx.destination);
  src.start(t);
}

function sndShot() { beep(880, 0.07, 'square', 0.05, 440); }
function sndEnemyHit() { noiseBurst(0.05, 0.06, 1500); beep(220, 0.05, 'square', 0.04, 110); }
function sndEnemyDestroy() { noiseBurst(0.22, 0.12, 900); }
