  [660, 880, 990, 1320].forEach((f, i) => beepAt(f, t + i * 0.11, 0.10, 'square', 0.07));
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function rand(a, b) { return a + Math.random() * (b - a); }
function randi(a, b) { return Math.floor(rand(a, b + 1)); }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function lerp(a, b, t) { return a + (b - a) * t; }

function bezierPoint(t, p0, p1, p2, p3) {
  const mt = 1 - t;
  const a = mt * mt * mt;
  const b = 3 * mt * mt * t;
  const c = 3 * mt * t * t;
  const d = t * t * t;
  return a * p0 + b * p1 + c * p2 + d * p3;
}

function rectOverlap(ax, ay, aw, ah, bx, by, bw, bh) {
  return ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;
}

function loadHigh() {
  try {
    return parseInt(localStorage.getItem('galaga.high') || '0', 10) || 0;
  } catch (e) {
    return 0;
  }
}
function saveHigh(v) {
  try { localStorage.setItem('galaga.high', String(v)); } catch (e) {}
}

// ---------------------------------------------------------------------------
// Starfield
